from __future__ import annotations
import argparse, base64, hashlib, zlib
from pathlib import Path

REL='lib/commerce/vlm-current-evidence-availability-matrix.ts'
EXPECTED_SHA='5e74d4eb203819c2f9e9b5f697a09c4d31c61bf77b0dcba01d351ae891b0b736'
EXPECTED_BYTES=12770
DATA=''

def materialize(root:Path):
    data=zlib.decompress(base64.b64decode(DATA))
    if len(data)!=EXPECTED_BYTES or hashlib.sha256(data).hexdigest()!=EXPECTED_SHA:
        raise SystemExit('nonprojected overlay identity mismatch')
    out=root/REL; out.parent.mkdir(parents=True,exist_ok=True); out.write_bytes(data)
    print(f'{REL} {len(data)} {EXPECTED_SHA}')

ap=argparse.ArgumentParser(); ap.add_argument('--root',required=True); a=ap.parse_args(); materialize(Path(a.root))
